mapper.select:
WITH RECURSIVE menu_tree AS ( -- [1] 가상 테이블 정의 시작 -- 앵커 멤버 SELECT m.menu_no AS menuNo , m.menu_name AS menuName , m.parent_no AS parentNo , m.menu_lev AS menuLev , m.sort_ord AS sortOrd , m.pro_no AS proNo , CAST(LPAD(m.sort_ord, 5, '0') AS CHAR(200)) AS path FROM menu m WHERE (m.parent_no IS NULL OR m.parent_no = 0) AND m.use_yn = 'Y'
UNION ALL
-- 재귀 멤버 SELECT m.menu_no , m.menu_name , m.parent_no , m.menu_lev , m.sort_ord , m.pro_no , CONCAT(mt.path, '/', LPAD(m.sort_ord, 5, '0')) FROM menu m INNER JOIN menu_tree mt ON m.parent_no = mt.menuNo WHERE m.use_yn = 'Y' -- [2] 가상 테이블 정의 끝 (여기에 ORDER BY가 있으면 안 됩니다!) ) -- [3] 메인 호출 쿼리 SELECT mt.menuNo , mt.menuName , mt.parentNo , mt.menuLev , mt.sortOrd , TRIM(LEADING '/' FROM p.pro_path) AS proPath FROM menu_tree mt LEFT JOIN program p ON mt.proNo = p.pro_no AND p.use_yn = 'Y' ORDER BY mt.path;
